UNIT_DATA = [{'crop': 'Rice', 'diseases': ['Rice Blast', 'Bacterial Leaf Blight (BLB)'], 'content': [{'title': 'Rice Blast', 'sections': {'Introduction': 'Rice blast is regarded as the single most destructive disease of cultivated rice worldwide. It attacks rice from nursery to maturity and can cause total crop failure under favourable conditions.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Sordariomycetes', 'Order: Magnaporthales', 'Family: Magnaporthaceae', 'Genus: Magnaporthe (teleomorph); Pyricularia (anamorph)', 'Species: Magnaporthe oryzae (= Pyricularia oryzae, syn. P. grisea)'], 'Etiology': ['Highly variable pathogen with numerous physiological races.', 'Wide host range within Poaceae; grassy weeds such as Digitaria and Echinochloa act as collateral hosts.', 'Excess nitrogen increases disease severity; potassium and silicon nutrition increase resistance.'], 'Symptoms': ['Leaf blast: spindle/eye-shaped spots with grey-white centre and dark brown margin.', 'Node blast: nodes become black/brown and may break.', "Neck blast: neck node becomes blackish-brown, constricted and may break, producing chalky/unfilled grains ('rotten neck')."], 'Disease Cycle': ['Overwinters as mycelium and conidia in infected seed, crop residue/stubble and grassy hosts.', 'Conidia are wind-disseminated; germination occurs within 6–8 hours.', 'Appressorium generates high turgor pressure for direct penetration.', 'New lesions sporulate after about 4–6 days, producing polycyclic secondary cycles.'], 'Epidemiology': ['RH >90% and 8–10 hours leaf wetness favour infection.', 'Optimum temperature: 25–28°C.', 'Cloudy weather, light rain, dense canopy and excess nitrogen aggravate disease.'], 'Management': ['Use healthy disease-free seed; hot-water treatment 52–54°C for 10 min.', 'Avoid excess/late nitrogen; use adequate K and Si; wider spacing and sanitation.', 'Use resistant/tolerant varieties and gene pyramiding.', 'Tricyclazole or other recommended fungicides; Pseudomonas fluorescens and Trichoderma as biological components.']}}, {'title': 'Bacterial Leaf Blight (BLB)', 'sections': {'Introduction': 'BLB is the most important bacterial disease of rice and is a major constraint in high-input irrigated and hybrid rice systems.', 'Taxonomic Classification': ['Kingdom: Bacteria', 'Phylum: Pseudomonadota (Proteobacteria)', 'Class: Gammaproteobacteria', 'Order: Xanthomonadales', 'Family: Xanthomonadaceae', 'Genus: Xanthomonas', 'Species: Xanthomonas oryzae pv. oryzae'], 'Etiology': ['Seed-borne; survives on weed hosts and rice stubble/ratoon.', 'Enters through hydathodes, insect wounds and root wounds during transplanting.', 'Wind/rain/storm injury creates fresh entry wounds.'], 'Symptoms': ['Water-soaked translucent lesions start at leaf tips/margins and enlarge downward.', 'Kresek phase: systemic wilting of young seedlings/transplants.', 'Pale yellow to white leaves in adult plants; bacterial ooze may appear on lesions.'], 'Disease Cycle': ['Primary inoculum comes from seed, stubble and collateral weeds.', 'Bacteria multiply at hydathodes and spread by wind-driven rain and irrigation/flood water.', 'After xylem colonisation, systemic multiplication causes blight or Kresek.'], 'Epidemiology': ['Standing water and flood irrigation are critical for spread.', '25–34°C and high humidity favour multiplication.', 'Storms and heavy rain create wounds; excess nitrogen increases susceptibility.'], 'Management': ['Certified pathogen-free seed; avoid clipping seedling tips.', 'Balanced fertilization; shallow/intermittent irrigation where feasible; sanitation.', 'Resistant varieties with Xa genes.', 'Seed treatment and foliar streptocycline/copper oxychloride as specified in the notes; Pseudomonas fluorescens root dip.']}}], 'mcqs': [{'question': 'Which organism causes rice blast?', 'options': ['Xanthomonas oryzae pv. oryzae', 'Magnaporthe oryzae', 'Puccinia arachidis', 'Cercospora canescens'], 'answer': 'Magnaporthe oryzae', 'explanation': 'The notes identify Magnaporthe oryzae (= Pyricularia oryzae) as the rice blast pathogen.'}, {'question': 'What is the most damaging phase of rice blast?', 'options': ['Collar rot', 'Leaf blast', 'Neck blast', 'Seedling blight'], 'answer': 'Neck blast', 'explanation': 'Neck blast can break the panicle base and produce chalky/unfilled grains.'}, {'question': 'Which condition strongly favours rice blast?', 'options': ['20°C and dry soil', 'RH >90% with 8–10 h leaf wetness', 'RH <40%', 'Continuous drought'], 'answer': 'RH >90% with 8–10 h leaf wetness', 'explanation': 'High humidity and prolonged dew/leaf wetness favour infection.'}, {'question': 'Which structure helps Pyricularia penetrate rice leaves directly?', 'options': ['Sclerotium', 'Appressorium', 'Uredinium', 'Oospore'], 'answer': 'Appressorium', 'explanation': 'The germ tube differentiates into a melanized appressorium that generates high turgor pressure.'}, {'question': 'BLB is caused by which bacterium?', 'options': ['Xanthomonas oryzae pv. oryzae', 'Fusarium oxysporum f. sp. cubense', 'Puccinia arachidis', 'Peronosclerospora sorghi'], 'answer': 'Xanthomonas oryzae pv. oryzae', 'explanation': 'The notes identify X. oryzae pv. oryzae as the BLB pathogen.'}, {'question': 'What is Kresek in BLB?', 'options': ['Fruit rot', 'Systemic wilting of young seedlings/transplants', 'Rust pustules', 'Leaf crinkle'], 'answer': 'Systemic wilting of young seedlings/transplants', 'explanation': 'Kresek is the systemic wilt phase of bacterial leaf blight.'}, {'question': 'Which is a major route of BLB spread in the field?', 'options': ['Flood/irrigation water', 'Only seed', 'Only insects', 'Only wind without water'], 'answer': 'Flood/irrigation water', 'explanation': 'Bacterial ooze can be carried by irrigation/flood water.'}, {'question': 'Which rice BLB management practice is emphasized?', 'options': ['Excess nitrogen', 'Continuous flooding', 'Resistant varieties with Xa genes', 'Removing all potassium'], 'answer': 'Resistant varieties with Xa genes', 'explanation': 'The notes emphasize resistant varieties carrying Xa genes.'}, {'question': 'Which nitrogen practice increases susceptibility to BLB?', 'options': ['Balanced N', 'Avoiding excess N', 'Excessive nitrogen fertilization', 'No nitrogen ever'], 'answer': 'Excessive nitrogen fertilization', 'explanation': 'Excess N markedly increases susceptibility.'}, {'question': 'Which organism is used as a biological component against rice blast/BLB in the notes?', 'options': ['Pseudomonas fluorescens', 'Bemisia tabaci', 'Myzus persicae', 'Puccinia'], 'answer': 'Pseudomonas fluorescens', 'explanation': 'Pseudomonas fluorescens is listed as a biological/induced-resistance component.'}], 'written_short': ['Define the etiology and epidemiology of rice blast.', 'What is the Kresek phase of bacterial leaf blight?', 'Name the causal organism and family of rice blast.', 'State two favourable conditions for BLB.', 'Mention two IDM measures for rice blast.'], 'written_long': 'Describe in detail the symptoms, disease cycle and integrated management of rice blast.'}, {'crop': 'Maize', 'diseases': ['Turcicum Leaf Blight (Northern Corn Leaf Blight)', 'Downy Mildew'], 'content': [{'title': 'Turcicum Leaf Blight', 'sections': {'Introduction': 'A widespread and economically important maize foliar disease, especially serious in cool, humid hill and rainy-season tracts.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Dothideomycetes', 'Order: Pleosporales', 'Family: Pleosporaceae', 'Genus: Exserohilum (anamorph); Setosphaeria (teleomorph)', 'Species: Exserohilum turcicum (= Helminthosporium turcicum); teleomorph Setosphaeria turcica'], 'Etiology': ['Primarily necrotrophic.', 'Several physiological races occur based on reaction to Ht resistance genes.', 'Survives on infected crop debris.'], 'Symptoms': ["Long elliptical grey-green to tan 'cigar-shaped' lesions, 2.5–15 cm long.", 'Lesions progress from lower to upper leaves and may coalesce.', 'Dark olivaceous spore masses may appear under humid conditions.'], 'Disease Cycle': ['Conidia and mycelium survive on infected leaf debris.', 'Conidia disperse by wind and rain-splash.', 'After about 7 days, lesions sporulate and produce repeated secondary cycles.'], 'Epidemiology': ['Cool moist weather: 18–27°C.', 'Heavy dew and leaf wetness >6 hours favour infection.', 'Dense planting and continuous maize monocropping increase risk.'], 'Management': ['Rotate with non-cereal crops; incorporate residues; improve spacing/drainage.', 'Use Ht1, Ht2, Ht3 or HtN resistant hybrids.', 'Mancozeb, Propiconazole or Zineb at first symptoms; Trichoderma residue treatment.']}}, {'title': 'Downy Mildew', 'sections': {'Introduction': 'A destructive systemic disease of maize caused by Peronosclerospora/Sclerophthora species depending on region.', 'Taxonomic Classification': ['Kingdom: Chromista (Stramenopila)', 'Phylum: Oomycota', 'Class: Oomycetes', 'Order: Peronosporales', 'Family: Peronosporaceae', 'Genus: Peronosclerospora', 'Species: Peronosclerospora sorghi; related species include P. maydis and P. philippinensis'], 'Etiology': ['Obligate biotrophic oomycete with coenocytic mycelium.', 'Oospores are important for long-term survival; airborne sporangia/conidia cause local secondary infections.', 'Seedling infection through the coleoptile can become systemic.'], 'Symptoms': ['Chlorotic streaks parallel to veins.', 'White/grey downy growth on leaf surfaces, especially in early morning.', 'Stunting, excessive tillering and tassel malformation; ears may fail or be malformed.'], 'Disease Cycle': ['Oospores germinate and infect young seedlings, establishing systemic infection.', 'Airborne sporangia from infected plants or collateral hosts cause local infections.', 'Infected plants sporulate; oospores persist in soil for several years.'], 'Epidemiology': ['20–25°C, high humidity and heavy dew favour infection.', 'Continuous maize/maize-sorghum sequences build inoculum.', 'Collateral grassy hosts sustain disease.'], 'Management': ['Rotate with non-graminaceous crops; rogue infected seedlings before sporulation.', 'Remove collateral grassy hosts and adjust sowing dates.', 'Use resistant/tolerant hybrids.', 'Metalaxyl seed treatment; biological control is not commonly relied upon.']}}], 'mcqs': [{'question': 'What is the characteristic lesion of Turcicum leaf blight?', 'options': ['Ring spot', 'Cigar-shaped lesion', 'Water-soaked bacterial ooze', 'Yellow mosaic'], 'answer': 'Cigar-shaped lesion', 'explanation': "The notes describe long elliptical grey-green to tan 'cigar-shaped' lesions."}, {'question': 'Turcicum leaf blight is caused by:', 'options': ['Exserohilum turcicum', 'Magnaporthe oryzae', 'Cercospora canescens', 'Colletotrichum gloeosporioides'], 'answer': 'Exserohilum turcicum', 'explanation': 'The pathogen is Exserohilum turcicum.'}, {'question': 'What weather favours Turcicum leaf blight?', 'options': ['Cool moist 18–27°C', 'Hot dry 35–40°C', 'Very dry 10°C', 'Flooded soil only'], 'answer': 'Cool moist 18–27°C', 'explanation': 'Cool moist conditions and heavy dew are conducive.'}, {'question': 'Where does Turcicum leaf blight primary inoculum commonly survive?', 'options': ['In infected leaf debris', 'Only in fruit', 'Only in seed embryos', 'In aphid stylets'], 'answer': 'In infected leaf debris', 'explanation': 'Conidia and mycelium survive on infected crop debris.'}, {'question': 'Downy mildew of maize is described as:', 'options': ['A systemic disease', 'Only a fruit disease', 'A rust', 'A bacterial wilt'], 'answer': 'A systemic disease', 'explanation': 'Seedling infection through the coleoptile can establish systemic infection.'}, {'question': 'Which organism causes the sorghum downy mildew of maize in the notes?', 'options': ['Peronosclerospora sorghi', 'Puccinia arachidis', 'Xanthomonas oryzae', 'Cercospora arachidicola'], 'answer': 'Peronosclerospora sorghi', 'explanation': 'The notes list P. sorghi as the main example.'}, {'question': 'Which structure is important for long-term survival of maize downy mildew?', 'options': ['Oospore', 'Urediniospore', 'Acervulus', 'Sclerotium only'], 'answer': 'Oospore', 'explanation': 'Thick-walled oospores persist in senescent tissue/soil.'}, {'question': 'Which temperature range favours maize downy mildew?', 'options': ['20–25°C', '40–45°C', '5–10°C', '30–35°C only'], 'answer': '20–25°C', 'explanation': 'Cool temperatures, high humidity and heavy dew favour disease.'}, {'question': 'Which is a key management measure for systemic downy mildew?', 'options': ['Metalaxyl seed treatment', 'No seed treatment', 'Excess N', 'Continuous maize'], 'answer': 'Metalaxyl seed treatment', 'explanation': 'The notes specify Metalaxyl seed treatment as highly effective for protecting seedlings.'}, {'question': 'Which crop rotation helps manage Turcicum leaf blight?', 'options': ['Continuous maize', 'Rotation with non-cereal crops', 'Maize-sorghum only', 'No rotation'], 'answer': 'Rotation with non-cereal crops', 'explanation': 'Rotation reduces debris-borne inoculum.'}], 'written_short': ['Name the causal organism of Turcicum leaf blight.', 'Why is maize downy mildew called a systemic disease?', 'State two favourable conditions for Turcicum leaf blight.', 'What is a collateral host? Give one example from maize downy mildew.', 'Mention two management measures for maize downy mildew.'], 'written_long': 'Explain how Peronosclerospora sorghi causes systemic infection in maize and describe management of downy mildew.'}, {'crop': 'Groundnut', 'diseases': ['Tikka Leaf Spot (Early & Late Leaf Spot)', 'Groundnut Rust'], 'content': [{'title': 'Tikka Leaf Spot (Early & Late Leaf Spot)', 'sections': {'Introduction': 'Tikka disease comprises early and late leaf spot and is a major groundnut foliar disease; it often occurs with rust in a damaging leaf spot-rust complex.', 'Taxonomic Classification': ['Early spot: Cercospora arachidicola (teleomorph Mycosphaerella arachidis)', 'Late spot: Cercosporidium (= Phaeoisariopsis) personatum (teleomorph Mycosphaerella berkeleyi)', 'Family: Mycosphaerellaceae'], 'Etiology': ['Both pathogens are seed- and soil/debris-borne.', 'Early spot is favoured by slightly cooler alternating wet-dry conditions; late spot by warmer, more humid conditions.', 'Continuous groundnut monocropping builds residue-borne inoculum.'], 'Symptoms': ['Early spot: brown spots with a distinct yellow halo, more prominent on upper leaf surface.', 'Late spot: darker/angular spots usually without yellow halo, with lower-surface sporulation.', 'Severe disease causes premature defoliation and reduced pod fill.'], 'Disease Cycle': ['Conidia/stromata survive on infected debris.', 'Conidia spread by wind and rain-splash and penetrate directly or via stomata.', 'New lesions sporulate after 10–14 days, producing polycyclic cycles.'], 'Epidemiology': ['25–30°C, warm humid weather and alternating wet-dry spells favour disease.', 'Dense canopy and high RH prolong leaf wetness.', 'Continuous groundnut cultivation sustains inoculum.'], 'Management': ['Rotate with non-host crops for 2–3 years; plough and destroy debris; timely sowing.', 'Use tolerant/resistant varieties where available.', 'Chlorothalonil, Mancozeb or Carbendazim+Mancozeb as recommended; Trichoderma/Pseudomonas as IDM components.']}}, {'title': 'Groundnut Rust', 'sections': {'Introduction': 'A widely distributed foliar disease that can form a damaging rust-tikka complex.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Basidiomycota', 'Class: Pucciniomycetes', 'Order: Pucciniales (Uredinales)', 'Family: Pucciniaceae', 'Genus: Puccinia', 'Species: Puccinia arachidis'], 'Etiology': ['Autoecious, macrocyclic rust; no alternate host is required.', 'Urediniospores are the main means of survival and rapid spread.', 'Survives on volunteer groundnut plants and crop debris.'], 'Symptoms': ['Small orange-brown powdery uredinia, mainly on lower leaf surface.', 'Chlorotic halo may surround pustules.', 'Heavily infected leaves dry and drop prematurely.'], 'Disease Cycle': ['Urediniospores disperse to new foliage.', 'They germinate on moisture and penetrate through stomata.', 'After about 10 days, uredinial pustules release new urediniospores for repeated cycles.'], 'Epidemiology': ['20–25°C and RH >95% with heavy dew favour infection.', 'Frequent light rain followed by sunshine promotes repeated cycles.', 'Volunteer plants and dense canopies accelerate epidemics.'], 'Management': ['Remove volunteers and crop debris; rotate with non-host crops.', 'Use moderately resistant/tolerant varieties.', 'Wettable sulphur, Mancozeb, Chlorothalonil or Hexaconazole as recommended; integrate Trichoderma.']}}], 'mcqs': [{'question': 'Which pathogen causes early leaf spot of groundnut?', 'options': ['Cercospora arachidicola', 'Puccinia arachidis', 'Peronosclerospora sorghi', 'Xanthomonas oryzae'], 'answer': 'Cercospora arachidicola', 'explanation': 'Early leaf spot is caused by C. arachidicola.'}, {'question': 'Which symptom helps distinguish early leaf spot?', 'options': ['Distinct yellow halo', 'No halo ever', 'Orange rust pustules', 'Ring spots on fruit'], 'answer': 'Distinct yellow halo', 'explanation': 'Early leaf spot typically has a distinct yellow chlorotic halo.'}, {'question': 'Late leaf spot is generally:', 'options': ['Darker and often without yellow halo', 'Always white', 'Bacterial ooze', 'A viral mosaic'], 'answer': 'Darker and often without yellow halo', 'explanation': 'Late leaf spot has darker angular spots and usually lacks a yellow halo.'}, {'question': 'A major epidemiological factor for tikka disease is:', 'options': ['Warm humid weather', 'Absolute drought', 'Very cold dry air', 'No leaf wetness'], 'answer': 'Warm humid weather', 'explanation': '25–30°C and wet-dry cycles favour disease.'}, {'question': 'Which pathogen causes groundnut rust?', 'options': ['Puccinia arachidis', 'Cercospora canescens', 'Magnaporthe oryzae', 'Mycosphaerella musicola'], 'answer': 'Puccinia arachidis', 'explanation': 'The rust pathogen is Puccinia arachidis.'}, {'question': 'Groundnut rust pustules are usually:', 'options': ['Orange-brown and powdery', 'Blue and watery', 'White and gelatinous', 'Yellow mosaic patches'], 'answer': 'Orange-brown and powdery', 'explanation': 'Uredinia are small orange-brown powdery pustules.'}, {'question': 'Groundnut rust is:', 'options': ['Autoecious and needs no alternate host', 'Heteroecious with two hosts', 'A virus', 'A bacterium'], 'answer': 'Autoecious and needs no alternate host', 'explanation': 'The notes describe it as an autoecious macrocyclic rust.'}, {'question': 'What temperature/RH combination favours rust?', 'options': ['20–25°C and RH >95%', '35°C and RH 20%', '5°C and RH 30%', '40°C and RH 40%'], 'answer': '20–25°C and RH >95%', 'explanation': 'Moderate temperature plus very high RH and dew favour rust.'}, {'question': 'Which practice reduces tikka inoculum?', 'options': ['2–3 year rotation with non-host crops', 'Continuous groundnut', 'Leaving all debris', 'Dense planting'], 'answer': '2–3 year rotation with non-host crops', 'explanation': 'Rotation and debris management reduce residue-borne inoculum.'}, {'question': 'Which biological agents are mentioned for groundnut leaf diseases?', 'options': ['Trichoderma viride or Pseudomonas fluorescens', 'Bemisia only', 'Aphids', 'Fusarium'], 'answer': 'Trichoderma viride or Pseudomonas fluorescens', 'explanation': 'Both are listed as IDM components.'}], 'written_short': ['Differentiate early and late leaf spot by causal organism.', 'State two favourable conditions for groundnut rust.', 'What is the main survival/spread spore of groundnut rust?', 'Mention two symptoms of late leaf spot.', 'State two IDM measures for the groundnut leaf spot-rust complex.'], 'written_long': 'Write a detailed note on the leaf spot-rust complex of groundnut, covering causal organisms, favourable conditions and integrated management.'}, {'crop': 'Green Gram', 'diseases': ['Mungbean Yellow Mosaic Virus (MYMV) Disease', 'Cercospora Leaf Spot'], 'content': [{'title': 'Mungbean Yellow Mosaic Virus (MYMV) Disease', 'sections': {'Introduction': 'Yellow mosaic is the most economically important disease of mungbean across South and South-East Asia.', 'Taxonomic Classification': ['Group II: circular ssDNA viruses', 'Family: Geminiviridae', 'Genus: Begomovirus', 'Species: Mungbean yellow mosaic virus / Mungbean yellow mosaic India virus', 'Vector: Whitefly, Bemisia tabaci'], 'Etiology': ['Bipartite ssDNA virus transmitted persistently and circulatively by Bemisia tabaci.', 'Virus survives in alternate leguminous weeds and off-season susceptible crops.', 'Severity is closely related to whitefly population build-up, favoured by warm dry weather.'], 'Symptoms': ['Yellow specks near veins enlarge into yellow-green mosaic patches.', 'Severe early infection can cause near-complete yellowing and stunting.', 'Flowering and pod-set decline; pods may be small, malformed and blotched.'], 'Disease Cycle': ['Whiteflies acquire virus while feeding on infected plants.', 'Virus circulates through gut/haemolymph to salivary glands.', 'Viruliferous whiteflies transmit virus during later feeding; infection can spread rapidly.'], 'Epidemiology': ['30–35°C and low rainfall favour whitefly multiplication.', 'Overlapping susceptible legumes maintain the reservoir.', 'Sowing time affects exposure to whitefly pressure.'], 'Management': ['Adjust sowing time; avoid overlapping susceptible legumes; rogue infected plants; remove weed hosts.', 'Use MYMV-resistant/tolerant varieties.', 'Manage whiteflies with recommended insecticides and yellow sticky traps; neem-based formulations can be integrated.']}}, {'title': 'Cercospora Leaf Spot', 'sections': {'Introduction': 'A common fungal foliar disease of mungbean, important in humid regions and seed crops.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Dothideomycetes', 'Order: Capnodiales', 'Family: Mycosphaerellaceae', 'Genus: Cercospora', 'Species: Cercospora canescens'], 'Etiology': ['Seed-borne and soil/debris-borne.', 'Warm humid weather and dense, poorly ventilated canopies favour build-up.'], 'Symptoms': ['Circular/angular brown spots with grey/tan centre and reddish-brown to purplish margin.', 'Severe spots coalesce, causing yellowing, drying and leaf shedding.', 'Lesions may also occur on stems and pods.'], 'Disease Cycle': ['Conidia and mycelium survive in seed and crop debris.', 'Conidia spread by wind/rain-splash and germinate on free moisture.', 'New lesions sporulate and create repeated secondary cycles.'], 'Epidemiology': ['Warm temperatures, RH >80%, frequent light rain/heavy dew and dense stands favour disease.'], 'Management': ['Disease-free seed, rotation, proper spacing and debris destruction.', 'Use tolerant varieties where available.', 'Thiram/Carbendazim seed treatment; Mancozeb or copper oxychloride foliar spray; Trichoderma seed treatment.']}}], 'mcqs': [{'question': 'MYMV is transmitted by:', 'options': ['Bemisia tabaci', 'Myzus persicae only', 'Puccinia', 'Trichoderma'], 'answer': 'Bemisia tabaci', 'explanation': 'The vector is the whitefly Bemisia tabaci.'}, {'question': 'MYMV transmission is described as:', 'options': ['Persistent and circulative', 'Non-persistent stylet-borne', 'Seed-only', 'Mechanical-only'], 'answer': 'Persistent and circulative', 'explanation': 'The notes specify persistent, circulative, non-propagative transmission.'}, {'question': 'Which condition favours whitefly build-up?', 'options': ['Warm dry weather', 'Continuous cold wet weather', 'Heavy frost', 'No sunlight'], 'answer': 'Warm dry weather', 'explanation': '30–35°C and low rainfall favour whitefly multiplication.'}, {'question': 'A key MYMV symptom is:', 'options': ['Yellow-green mosaic patches', 'Orange rust pustules', 'Cigar lesions', 'Panama wilt'], 'answer': 'Yellow-green mosaic patches', 'explanation': 'Yellow specks enlarge into irregular yellow-green mosaic patches.'}, {'question': 'Which is a key MYMV management method?', 'options': ['Resistant/tolerant varieties', 'Only fungicides', 'No roguing', 'Continuous susceptible cropping'], 'answer': 'Resistant/tolerant varieties', 'explanation': 'Host resistance is described as the most effective/economical option.'}, {'question': 'Cercospora leaf spot of mungbean is caused by:', 'options': ['Cercospora canescens', 'Puccinia arachidis', 'PRSV', 'Fusarium oxysporum'], 'answer': 'Cercospora canescens', 'explanation': 'The notes identify C. canescens.'}, {'question': 'Cercospora leaf spot favours:', 'options': ['Warm humid weather and dense canopy', 'Very dry air', 'Frost', 'No leaf wetness'], 'answer': 'Warm humid weather and dense canopy', 'explanation': 'RH >80%, rain/dew and dense stands favour it.'}, {'question': 'Cercospora conidia spread mainly by:', 'options': ['Wind and rain-splash', 'Only seed', 'Only aphids', 'Only irrigation pipes'], 'answer': 'Wind and rain-splash', 'explanation': 'The disease cycle specifies wind and rain-splash dispersal.'}, {'question': 'Which seed treatment is listed for Cercospora leaf spot?', 'options': ['Thiram or Carbendazim', 'Metalaxyl only', 'No treatment', 'Copper wire'], 'answer': 'Thiram or Carbendazim', 'explanation': 'The notes specify Thiram or Carbendazim at 2 g/kg seed.'}, {'question': 'Which biological treatment is listed?', 'options': ['Trichoderma viride', 'Bemisia tabaci', 'PRSV', 'Puccinia'], 'answer': 'Trichoderma viride', 'explanation': 'Trichoderma viride seed treatment is listed.'}], 'written_short': ['What type of virus causes MYMV and what is its vector?', 'State two symptoms of mungbean yellow mosaic.', 'Why are warm dry conditions important in MYMV epidemiology?', 'Name the causal organism of Cercospora leaf spot.', 'Mention two management measures for Cercospora leaf spot.'], 'written_long': 'Describe the biology of whitefly-transmitted yellow mosaic virus disease in mungbean and outline an integrated management programme.'}, {'crop': 'Black Gram', 'diseases': ['Yellow Mosaic Virus Disease', 'Leaf Crinkle Virus Disease'], 'content': [{'title': 'Yellow Mosaic Virus Disease', 'sections': {'Introduction': 'Black gram yellow mosaic is caused by the same MYMV/MYMIV begomovirus complex described for green gram.', 'Taxonomic Classification': ['Group II: circular ssDNA viruses', 'Family: Geminiviridae', 'Genus: Begomovirus', 'Species: Mungbean yellow mosaic virus / Mungbean yellow mosaic India virus', 'Vector: Bemisia tabaci'], 'Etiology': ['Bipartite ssDNA begomovirus transmitted persistently and circulatively by whitefly.', 'Disease severity is governed primarily by whitefly population dynamics.'], 'Symptoms': ['Bright yellow mosaic mottling on trifoliate leaves, progressing to complete yellowing in severe/early infection.', 'Stunting, reduced pod number and small poorly filled/blotched pods.'], 'Disease Cycle': ['Persistent, circulative whitefly-mediated transmission cycle, as in green gram MYMV.'], 'Epidemiology': ['Warm dry weather favours whitefly build-up.', 'Overlapping cultivation with susceptible legumes drives epidemics.'], 'Management': ['Timely sowing, roguing, weed-host removal and avoiding overlapping legume sequences.', 'Resistant/tolerant varieties such as Pant U-19 and T9 are emphasized in the notes.', 'Imidacloprid/Thiamethoxam and yellow sticky traps; neem-based sprays can be integrated.']}}, {'title': 'Leaf Crinkle Virus Disease', 'sections': {'Introduction': 'Urdbean leaf crinkle disease is a distinct, highly seed-transmissible viral disease and is important in seed production.', 'Taxonomic Classification': ['Nature: virus complex', 'Older literature: provisionally associated with Comoviridae/Comovirus; placement debated', 'Transmission: highly seed-transmissible; also mechanical through sap and suspected whitefly involvement'], 'Etiology': ['Very high seed transmission (reports in the notes: 50–90%) makes infected seed the principal primary source.', 'Secondary spread can occur mechanically through sap and possibly insect vectors.'], 'Symptoms': ['Leaves become crinkled, curled downward, thickened, brittle and dark green.', 'Plants become bushy and stunted with shortened internodes.', 'Flowering may be drastically reduced or suppressed, causing severe yield loss.'], 'Disease Cycle': ['Plants raised from infected seed are diseased from emergence.', 'Sap from infected plants can mechanically transmit the virus to neighbouring plants.'], 'Epidemiology': ['Incidence is closely tied to seed-lot infection level.', '25–30°C supports vegetative spread and contact transmission.'], 'Management': ['Use virus-free certified seed and rogue infected plants before flowering.', 'Avoid very close spacing.', 'Use tolerant/resistant varieties such as T9 and Pant U-19 where recommended.', 'No specific curative chemical control exists; vector control may be used if a vector is confirmed.']}}], 'mcqs': [{'question': 'Black gram yellow mosaic is transmitted by:', 'options': ['Bemisia tabaci', 'Aphis gossypii only', 'Puccinia', 'Trichoderma'], 'answer': 'Bemisia tabaci', 'explanation': 'Whitefly is the vector.'}, {'question': 'The black gram yellow mosaic virus group is:', 'options': ['Begomovirus', 'Potyvirus', 'Fusarium', 'Cercospora'], 'answer': 'Begomovirus', 'explanation': 'The notes classify MYMV/MYMIV as begomoviruses.'}, {'question': 'Which symptom is characteristic of black gram yellow mosaic?', 'options': ['Bright yellow mosaic mottling', 'Leaf crinkling only', 'Orange pustules', 'Cigar lesions'], 'answer': 'Bright yellow mosaic mottling', 'explanation': 'Bright yellow mosaic mottling occurs on trifoliate leaves.'}, {'question': 'Which weather favours black gram yellow mosaic epidemics?', 'options': ['Warm dry weather', 'Cold wet weather', 'Frost', 'Heavy snow'], 'answer': 'Warm dry weather', 'explanation': 'Warm dry weather favours whitefly build-up.'}, {'question': 'A major management strategy for black gram yellow mosaic is:', 'options': ['Resistant/tolerant varieties', 'Only fungicide sprays', 'Leaving infected plants', 'No vector management'], 'answer': 'Resistant/tolerant varieties', 'explanation': 'The notes call resistance the most reliable strategy.'}, {'question': 'Leaf crinkle disease has especially high:', 'options': ['Seed transmission', 'Rust transmission', 'Fruit transmission', 'Water transmission'], 'answer': 'Seed transmission', 'explanation': 'It is highly seed-transmissible and seed is the principal primary source.'}, {'question': 'Leaf crinkle symptoms include:', 'options': ['Crinkled, thickened, brittle dark-green leaves', 'Yellow rings on fruit', 'Orange rust pustules', 'Water-soaked bacterial lesions'], 'answer': 'Crinkled, thickened, brittle dark-green leaves', 'explanation': 'These are characteristic symptoms in the notes.'}, {'question': 'The older literature provisionally associated leaf crinkle virus with:', 'options': ['Comoviridae/Comovirus', 'Potyviridae/Potyvirus', 'Pucciniaceae', 'Mycosphaerellaceae'], 'answer': 'Comoviridae/Comovirus', 'explanation': 'The notes explicitly state this older provisional association and note that placement is debated.'}, {'question': 'The most important primary control for leaf crinkle is:', 'options': ['Virus-free certified seed', 'Continuous dense sowing', 'Excess nitrogen', 'Only foliar fungicide'], 'answer': 'Virus-free certified seed', 'explanation': 'Clean seed is described as the single most important control.'}, {'question': 'Which statement about leaf crinkle chemical control is correct?', 'options': ['No specific curative chemical control exists', 'Fungicide cures it', 'Copper always cures it', 'Metalaxyl cures the virus'], 'answer': 'No specific curative chemical control exists', 'explanation': 'The notes state there is no specific curative chemical control for the virus itself.'}], 'written_short': ['Name the vector of black gram yellow mosaic virus.', 'Compare yellow mosaic and leaf crinkle disease transmission.', 'State two symptoms of leaf crinkle disease.', 'Why is certified seed important in leaf crinkle management?', 'Mention two management measures for black gram yellow mosaic.'], 'written_long': 'Compare and contrast yellow mosaic virus disease and leaf crinkle virus disease of black gram with respect to transmission and management.'}, {'crop': 'Banana', 'diseases': ['Panama Wilt (Fusarium Wilt)', 'Sigatoka Leaf Spot (Yellow Sigatoka)'], 'content': [{'title': 'Panama Wilt (Fusarium Wilt)', 'sections': {'Introduction': 'Panama disease is caused by the soil-borne Fusarium oxysporum f. sp. cubense; Race 1 affected Gros Michel and TR4 threatens Cavendish cultivars.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Sordariomycetes', 'Order: Hypocreales', 'Family: Nectriaceae', 'Genus: Fusarium', 'Species: Fusarium oxysporum f. sp. cubense (races 1, 2, 4/TR4)'], 'Etiology': ['Produces microconidia, macroconidia and thick-walled chlamydospores.', 'Chlamydospores can survive in soil for 20–30 years or more.', 'Enters through root tips/wounds, including nematode damage, and colonises xylem.'], 'Symptoms': ['Yellowing starts in oldest leaves and progresses to younger leaves.', "Leaves wilt; petioles snap and dead leaves form a 'skirt'.", 'Pseudostem base/rhizome shows discoloured vascular strands.'], 'Disease Cycle': ['Chlamydospores/mycelium survive in soil.', 'They germinate near roots and infect root tips/wounds.', 'Microconidia move upward in the transpiration stream through xylem.', 'Spread occurs via infected planting material, soil, irrigation water and tools/footwear.'], 'Epidemiology': ['Acidic sandy soils and poor drainage/waterlogging favour disease.', 'Nematode damage increases infection through wounds.', 'Continuous susceptible banana cultivation sustains inoculum.'], 'Management': ['Certified pathogen-free tissue-culture planting material is the key preventive measure.', 'Strict sanitation, movement control, drainage and nematode management.', 'Use resistant/tolerant cultivars; chemical control is generally uneconomical/ineffective.', 'Organic matter, Trichoderma and Pseudomonas may provide suppressive effects; lime is advised to reduce severity.']}}, {'title': 'Sigatoka Leaf Spot (Yellow Sigatoka)', 'sections': {'Introduction': 'Yellow Sigatoka is a major foliar disease of banana that reduces photosynthetic area, bunch weight and fruit quality.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Dothideomycetes', 'Order: Capnodiales', 'Family: Mycosphaerellaceae', 'Genus: Mycosphaerella (teleomorph); Pseudocercospora (anamorph)', 'Species: Mycosphaerella musicola (anamorph Pseudocercospora musae)'], 'Etiology': ['Survives on infected leaf debris.', 'Both sexual ascospores and asexual conidia occur.', 'Ascospores provide longer-distance primary spread; conidia provide rain-splash secondary spread.'], 'Symptoms': ['Minute yellowish streaks progress to elongated yellow-brown streaks.', 'Later oval brown spots with yellow halo and necrotic lesions develop.', 'Severe infection causes leaf blighting and premature leaf death, reducing bunch development.'], 'Disease Cycle': ['Ascospores from pseudothecia on dead debris are wind-borne to young leaves.', 'Lesions produce conidia that spread by rain-splash.', "Dead leaves become the next season's inoculum source."], 'Epidemiology': ['25–28°C with high rainfall/RH favours infection.', 'Dense, poorly drained plantations maintain leaf wetness.', 'Poor sanitation allows inoculum build-up.'], 'Management': ['Regular deleafing and removal of heavily infected/dead leaves.', 'Wider spacing, drainage and balanced fertilization.', 'Use resistant/tolerant cultivars where available.', 'Protective fungicides such as Propiconazole, Mancozeb or Chlorothalonil; Trichoderma leaf-litter treatment as support.']}}], 'mcqs': [{'question': 'Panama wilt is caused by:', 'options': ['Fusarium oxysporum f. sp. cubense', 'Mycosphaerella musicola', 'PRSV', 'Puccinia arachidis'], 'answer': 'Fusarium oxysporum f. sp. cubense', 'explanation': 'Foc causes Panama wilt.'}, {'question': 'Which structure gives Fusarium wilt long soil survival?', 'options': ['Chlamydospore', 'Conidium only', 'Uredinium', 'Acervulus'], 'answer': 'Chlamydospore', 'explanation': 'Thick-walled chlamydospores allow long-term soil survival.'}, {'question': 'Foc primarily enters banana through:', 'options': ['Root tips/wounds', 'Leaf stomata only', 'Fruit surface only', 'Aphid stylets'], 'answer': 'Root tips/wounds', 'explanation': 'Root wounds and root tips are major entry points.'}, {'question': 'A definitive diagnostic sign of Panama wilt is:', 'options': ['Discoloured vascular strands', 'Yellow mosaic', 'Orange pustules', 'Cigar lesions'], 'answer': 'Discoloured vascular strands', 'explanation': 'Vascular discoloration in the pseudostem base/corm is diagnostic.'}, {'question': 'Which practice is the key preventive measure for Panama wilt?', 'options': ['Certified pathogen-free tissue-culture planting material', 'Continuous susceptible planting', 'Moving soil between fields', 'Waterlogging'], 'answer': 'Certified pathogen-free tissue-culture planting material', 'explanation': 'The notes identify clean tissue-culture planting material as the single most important preventive measure.'}, {'question': 'Yellow Sigatoka is caused by:', 'options': ['Mycosphaerella musicola', 'Fusarium oxysporum', 'PRSV', 'Cercospora canescens'], 'answer': 'Mycosphaerella musicola', 'explanation': 'The pathogen is M. musicola (anamorph Pseudocercospora musae).'}, {'question': 'In Yellow Sigatoka, ascospores mainly provide:', 'options': ['Long-distance primary spread', 'Only root infection', 'Seed transmission', 'Mechanical sap transmission'], 'answer': 'Long-distance primary spread', 'explanation': 'Ascospores are wind-borne primary inoculum.'}, {'question': 'Conidia of Yellow Sigatoka mainly provide:', 'options': ['Rain-splash secondary spread', 'Long-term soil survival only', 'Vector transmission', 'Seed transmission'], 'answer': 'Rain-splash secondary spread', 'explanation': 'Conidia spread rapidly within plantations by rain-splash.'}, {'question': 'Which conditions favour Yellow Sigatoka?', 'options': ['25–28°C with high rainfall/RH', 'Very dry 10°C', 'Frost', 'Hot dry 40°C'], 'answer': '25–28°C with high rainfall/RH', 'explanation': 'Warm, wet, humid conditions favour disease.'}, {'question': 'A key cultural practice for Yellow Sigatoka is:', 'options': ['Regular deleafing', 'Continuous dense planting', 'Waterlogging', 'Leaving dead leaves'], 'answer': 'Regular deleafing', 'explanation': 'Removing heavily infected/dead leaves reduces inoculum.'}], 'written_short': ['What are chlamydospores and why are they important in Panama wilt?', 'State two symptoms of Panama wilt.', 'Why is Panama wilt difficult to manage?', 'Distinguish ascospore and conidial roles in Yellow Sigatoka.', 'Mention two IDM measures for Yellow Sigatoka.'], 'written_long': 'Discuss why Panama wilt of banana is one of the most difficult plant diseases to manage, referring to pathogen survival, races and control options.'}, {'crop': 'Papaya', 'diseases': ['Papaya Ring Spot Virus (PRSV) Disease', 'Anthracnose'], 'content': [{'title': 'Papaya Ring Spot Virus (PRSV) Disease', 'sections': {'Introduction': 'Papaya ring spot is a highly destructive viral disease and a major constraint to papaya production.', 'Taxonomic Classification': ['Group IV: positive-sense ssRNA viruses', 'Family: Potyviridae', 'Genus: Potyvirus', 'Species: Papaya ringspot virus (PRSV), strain P and strain W', 'Vector: Aphids such as Myzus persicae and Aphis gossypii'], 'Etiology': ['Flexuous filamentous potyvirus transmitted by aphids non-persistently (stylet-borne).', 'PRSV is not seed-transmitted in true seed; primary inoculum comes from infected papaya and nearby cucurbit hosts.', 'Brief aphid probing is enough for transmission, making insecticides alone poor at stopping spread.'], 'Symptoms': ["Mosaic mottling and vein clearing; leaves may develop narrow 'shoestring' appearance.", 'Water-soaked/oily dark green streaks on petioles and upper stem.', 'Concentric ring spots on fruit, distorted/reduced fruit and severe stunting.'], 'Disease Cycle': ['Aphids briefly probe infected papaya/cucurbits and acquire virus.', 'Virus remains on the stylet for a short period.', 'Winged aphids then inoculate healthy plants during exploratory probing.'], 'Epidemiology': ['Proximity to cucurbits is a strong risk factor.', 'Warm weather and active aphid flight increase inoculative probing.', 'Disease may spread rapidly across an orchard.'], 'Management': ['Isolate new orchards from cucurbits and old infected papaya; rogue infected plants.', 'Raise seedlings under insect-proof screens.', 'Use tolerant/resistant or approved transgenic resistant cultivars where available.', 'Because transmission is non-persistent, reflective mulches and mineral oils can be more useful for probing behaviour than insecticides alone.']}}, {'title': 'Anthracnose', 'sections': {'Introduction': 'Papaya anthracnose is an important post-harvest disease characterized by latent/quiescent infection of fruit.', 'Taxonomic Classification': ['Kingdom: Fungi', 'Phylum: Ascomycota', 'Class: Sordariomycetes', 'Order: Glomerellales', 'Family: Glomerellaceae', 'Genus: Colletotrichum (anamorph); Glomerella (teleomorph)', 'Species: Colletotrichum gloeosporioides (teleomorph Glomerella cingulata)'], 'Etiology': ['Infects green immature fruit but often remains quiescent until ripening.', 'Also causes leaf spots and survives on plant debris.', 'High humidity and fruit injury favour expression and spread.'], 'Symptoms': ['Ripening fruit develops water-soaked, sunken circular spots that enlarge and turn brown/black.', 'Pink-orange gelatinous spore masses may develop under humid conditions.', 'Severe fruit rotting makes produce unmarketable.'], 'Disease Cycle': ['Conidia from infected leaves, mummified fruit and debris spread mainly by rain-splash.', 'They penetrate green fruit and remain latent.', 'Ripening permits renewed fungal growth and production of new acervuli/conidia.'], 'Epidemiology': ['25–30°C, high humidity and frequent rain favour infection.', 'Harvesting/grading/packing injuries greatly increase rot.', 'Poor sanitation sustains inoculum.'], 'Management': ['Remove infected leaves, mummified fruit and debris; handle fruit carefully.', 'Avoid overhead irrigation late in fruit development; improve drainage/spacing.', 'Resistant commercial cultivars are limited.', 'Carbendazim or Mancozeb pre-harvest; hot-water treatment about 48°C for 20 min; Trichoderma/antagonistic yeasts as supplementary measures.']}}], 'mcqs': [{'question': 'PRSV belongs to which virus family?', 'options': ['Potyviridae', 'Geminiviridae', 'Comoviridae', 'Pucciniaceae'], 'answer': 'Potyviridae', 'explanation': 'The notes classify PRSV under Potyviridae, genus Potyvirus.'}, {'question': 'PRSV is transmitted by aphids in a:', 'options': ['Non-persistent stylet-borne manner', 'Persistent circulative manner', 'Seed-borne manner', 'Soil-borne manner'], 'answer': 'Non-persistent stylet-borne manner', 'explanation': 'Brief aphid probing can acquire and transmit PRSV.'}, {'question': 'Why can insecticides alone fail against PRSV?', 'options': ['Aphids transmit virus during brief probing', 'Virus is soil-borne', 'Virus is seed-borne', 'Fungus survives for decades'], 'answer': 'Aphids transmit virus during brief probing', 'explanation': 'The notes emphasize transient probing and rapid loss of infectivity.'}, {'question': 'A characteristic PRSV fruit symptom is:', 'options': ['Concentric ring spots', 'Orange uredinia', 'Cigar lesions', 'Vascular browning'], 'answer': 'Concentric ring spots', 'explanation': 'Ring spots are characteristic on papaya fruit.'}, {'question': 'Which nearby crop can act as an important PRSV reservoir?', 'options': ['Cucurbits', 'Rice', 'Banana only', 'Groundnut only'], 'answer': 'Cucurbits', 'explanation': 'The notes emphasize proximity to cucurbits as a risk factor.'}, {'question': 'A key PRSV management strategy is:', 'options': ['Roguing infected plants and using resistant/tolerant cultivars', 'Only fungicides', 'Continuous planting beside cucurbits', 'No isolation'], 'answer': 'Roguing infected plants and using resistant/tolerant cultivars', 'explanation': 'Both are emphasized in IDM.'}, {'question': 'Papaya anthracnose is caused by:', 'options': ['Colletotrichum gloeosporioides', 'Magnaporthe oryzae', 'Puccinia arachidis', 'Bemisia tabaci'], 'answer': 'Colletotrichum gloeosporioides', 'explanation': 'The notes identify C. gloeosporioides.'}, {'question': 'Quiescent infection means the anthracnose infection:', 'options': ['Remains latent in green fruit until ripening', 'Is immediately fatal', 'Only occurs in roots', 'Is transmitted by whitefly'], 'answer': 'Remains latent in green fruit until ripening', 'explanation': 'The fungus can remain latent until physiological changes at ripening allow active growth.'}, {'question': 'Which conditions favour papaya anthracnose?', 'options': ['25–30°C and high humidity', 'Cold dry weather', 'Frost', 'Very low humidity'], 'answer': '25–30°C and high humidity', 'explanation': 'Warm temperatures, high humidity and rain favour disease.'}, {'question': 'Which post-harvest treatment is listed for papaya anthracnose?', 'options': ['Hot-water treatment around 48°C for 20 min', 'Metalaxyl seed treatment', 'Whitefly trap', 'Rice seed treatment'], 'answer': 'Hot-water treatment around 48°C for 20 min', 'explanation': 'The notes list hot-water treatment to arrest latent infections.'}], 'written_short': ['What is non-persistent transmission of PRSV?', 'State two characteristic symptoms of PRSV.', 'Why can insecticides alone fail against PRSV?', 'Explain quiescent infection in papaya anthracnose.', 'Mention two management measures for papaya anthracnose.'], 'written_long': 'Explain the biology of non-persistent aphid transmission of Papaya Ringspot Virus and discuss why insecticides alone fail to control its spread.'}]
